package net.muxigame.core.feature.ysmassets;

import com.google.gson.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.muxigame.minigames.TrustedAccounts;
import java.nio.file.*;
import java.util.*;

/** Actual Web snapshots and Core policy A; runtime/MC listeners are explicit fixtures. */
public final class YsmAppearanceATest {
    static int checks;static String a,b,p,sha;static final Map<String,YsmAssetSnapshot> states=new HashMap<>();
    static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    static void denied(Runnable task,String message){boolean rejected=false;try{task.run();}catch(IllegalArgumentException|IllegalStateException expected){rejected=true;}check(rejected,message);}
    static ServerPlayer player(MinecraftServer server,String uid){var actor=new ServerPlayer(server,uid,YsmAssetProtocolTest.uuid(uid));TrustedAccounts.admitTerminal(actor,Long.parseLong(uid));return actor;}
    static void stage(YsmAssetCoordinator core,YsmAssetProtocolTest.NativeFixture runtime,String name){var state=states.get(name);check(!core.stage(state,YsmAssetProtocolTest.generation(state)).active(),"staging remains inactive");runtime.ready(state);}
    static void policyAndTransitions(){
        var server=new MinecraftServer();var owner=player(server,"10001");var otherOwner=player(server,"10002");var viewer=player(server,"10003");var ca=YsmTrustedPlayer.capture(owner);var cb=YsmTrustedPlayer.capture(otherOwner);var cc=YsmTrustedPlayer.capture(viewer);var runtime=new YsmAssetProtocolTest.NativeFixture();var core=new YsmAssetCoordinator(server::isSameThread,runtime);
        check(YsmAssetCoordinator.privateAppearancePolicy()==YsmAssetCoordinator.PrivateAppearancePolicy.OWNER_SELECTION_OBSERVER_RENDER,"A is the accepted policy");
        stage(core,runtime,"privateA");check(core.list(ca).stream().anyMatch(m->m.modelId().equals(a)),"owner lists own private reference");check(core.list(cc).isEmpty(),"observer private selection catalog empty");
        denied(()->core.renderPermit(cc,ca,core.revision()),"unworn private upload is not a render grant");denied(()->core.select(cc,a,core.revision(),"forged-private-selection"),"guessed private selection rejected by server");
        core.select(ca,a,core.revision(),"owner-private-wear");var rendering=core.renderPermit(cc,ca,core.revision());core.validateRenderPermit(cc,ca,rendering);
        check(rendering.usage().equals("render_only")&&rendering.sha256().equals(sha)&&rendering.contentId().equals(p),"observer has render-only resource grant");check(core.canReceivePrivateRenderBytes(cc,a,core.revision()),"legacy query derives authorized worn target");
        runtime.tracking=false;denied(()->core.renderPermit(cc,ca,core.revision()),"untracked observer cannot receive display resources");denied(()->core.validateRenderPermit(cc,ca,rendering),"tracking removal fences ongoing render chunks");runtime.tracking=true;core.validateRenderPermit(cc,ca,rendering);check(rendering.usage().equals("render_only"),"current tracking relation permits display without selection ownership");
        runtime.worn.put(owner.connection,"builtin_default");denied(()->core.renderPermit(cc,ca,core.revision()),"native reset outside Core invalidates assumed worn target");denied(()->core.validateRenderPermit(cc,ca,rendering),"cached Core selection alone cannot authorize stale native appearance");runtime.worn.put(owner.connection,a);core.validateRenderPermit(cc,ca,rendering);check(rendering.sha256().equals(sha),"actual current native wearer state is checked without claiming file erasure");
        denied(()->core.metadata(cc,a,core.revision()),"render grant cannot expose private selection metadata");denied(()->core.downloadPermit(cc,a,core.revision()),"render grant cannot become owner download/select permit");denied(()->core.select(cc,a,core.revision(),"cached-resource-selection"),"cached render resources cannot grant selection");denied(()->core.select(cc,p,core.revision(),"private-content-alias"),"private public-id alias rejected");denied(()->core.select(cc,sha,core.revision(),"private-hash-alias"),"private content hash rejected");
        Set<String> receivedResourceFixture=new HashSet<>();receivedResourceFixture.add(rendering.sha256());
        runtime.duringWear=()->denied(()->core.renderPermit(cc,ca,core.revision()),"partial/unconfirmed wear cannot issue rendering");core.select(ca,a,core.revision(),"owner-rewear");runtime.duringWear=null;denied(()->core.validateRenderPermit(cc,ca,rendering),"old render handle fenced after another wear confirmation");
        var second=core.renderPermit(cc,ca,core.revision());var otherCore=new YsmAssetCoordinator(server::isSameThread,runtime);denied(()->otherCore.validateRenderPermit(cc,ca,second),"render grant from another coordinator rejected");otherCore.close();
        long beforeTrackingRevision=core.revision();runtime.duringTracking=()->stage(core,runtime,"sharedPrivate");denied(()->core.renderPermit(cc,ca,beforeTrackingRevision),"revision changed during native tracking check cannot bless old request");
        stage(core,runtime,"publicA");check(core.list(cc).stream().anyMatch(m->m.modelId().equals(p)),"public content listed to observer");var publicUse=core.select(cc,p,core.revision(),"former-public-selection");var publicRender=core.renderPermit(cb,cc,core.revision());core.validateRenderPermit(cb,cc,publicRender);
        runtime.cache=false;runtime.peers=false;stage(core,runtime,"privateAgain");
        check(core.reconcile().pendingFallbacks()==1&&runtime.worn.get(viewer.connection).equals("builtin_default"),"former public wearer reset, authority/peer ACK still pending");check(runtime.worn.get(owner.connection).equals(a),"private owner remains wearing owned model");check(core.list(cc).isEmpty(),"former public directory entry removed");denied(()->core.validatePermit(cc,publicUse),"former public selection permit revoked");denied(()->core.validateRenderPermit(cb,cc,publicRender),"former unauthorized wear cannot keep render grant");
        var privateRender=core.renderPermit(cc,ca,core.revision());core.validateRenderPermit(cc,ca,privateRender);check(privateRender.sha256().equals(sha),"A still renders authorized owner while unrelated wearer fallback pending");denied(()->core.select(cc,a,core.revision(),"private-after-toggle"),"public-to-private never adds observer own permission");
        runtime.cache=true;runtime.peers=true;check(core.reconcile().pendingFallbacks()==0,"selection authority and appearance ACK allow pending reconciliation");
        stage(core,runtime,"deletedA");check(runtime.worn.get(owner.connection).equals("builtin_default"),"deleting logical owner reference resets its wearer");check(core.list(ca).isEmpty(),"deleted owner reference leaves directory");denied(()->core.validateRenderPermit(cc,ca,privateRender),"deletion fences prior rendering");denied(()->core.renderPermit(cc,ca,core.revision()),"deleted wearer cannot grant fresh rendering");check(receivedResourceFixture.contains(sha),"previously delivered render file may remain, without authority");denied(()->core.select(cc,a,core.revision(),"deleted-cached-selection"),"retained render resource cannot resurrect deleted selection");
        core.select(cb,b,core.revision(),"independent-owned-reference");var independent=core.renderPermit(cc,cb,core.revision());core.validateRenderPermit(cc,cb,independent);check(independent.sha256().equals(sha),"independent valid reference can still render same bytes");denied(()->core.validateRenderPermit(cc,cb,privateRender),"shared content cannot transfer another wearer's old grant");
        stage(core,runtime,"deletedBoth");denied(()->core.validateRenderPermit(cc,cb,independent),"last-reference deletion fences render");check(runtime.worn.get(otherOwner.connection).equals("builtin_default"),"last-reference wearer reset");
        stage(core,runtime,"restoredA");check(core.list(cc).isEmpty(),"restore defaults private");denied(()->core.renderPermit(cc,ca,core.revision()),"restore is not an automatic wear");core.select(ca,a,core.revision(),"restore-owner-wear");var restored=core.renderPermit(cc,ca,core.revision());core.validateRenderPermit(cc,ca,restored);
        core.close();denied(()->core.validateRenderPermit(cc,ca,restored),"shutdown invalidates render delivery");
    }
    static void identityFences(){
        var server=new MinecraftServer();var owner=player(server,"10001");var observer=player(server,"10003");var registry=new YsmConnectionRegistry(server,"fixture-A-policy");registry.bindVerified(owner);registry.bindVerified(observer);var ca=registry.connectionFor(owner);var cc=registry.connectionFor(observer);var runtime=new YsmAssetProtocolTest.NativeFixture();var core=new YsmAssetCoordinator(server::isSameThread,runtime);stage(core,runtime,"privateA");core.select(ca,a,core.revision(),"registered-owner-wear");var grant=core.renderPermit(cc,ca,core.revision());
        registry.bindVerified(observer);var newObserver=registry.connectionFor(observer);denied(()->core.validateRenderPermit(newObserver,ca,grant),"same-listener observer reauth fences original grant");var renewed=core.renderPermit(newObserver,ca,core.revision());core.validateRenderPermit(newObserver,ca,renewed);
        registry.bindVerified(owner);var newOwner=registry.connectionFor(owner);denied(()->core.validateRenderPermit(newObserver,newOwner,renewed),"same-listener wearer reauth fences original wear");denied(()->core.renderPermit(newObserver,newOwner,core.revision()),"new Auth generation cannot reuse old selected binding");core.reconcile();core.select(newOwner,a,core.revision(),"new-auth-owner-wear");var live=core.renderPermit(newObserver,newOwner,core.revision());
        TrustedAccounts.revokeTerminal(observer);denied(()->core.validateRenderPermit(newObserver,newOwner,live),"observer Auth expiry aborts render chunk");TrustedAccounts.admitTerminal(observer,10003);registry.bindVerified(observer);var freshObserver=registry.connectionFor(observer);var after=core.renderPermit(freshObserver,newOwner,core.revision());var finalObserver=freshObserver;
        TrustedAccounts.revokeTerminal(owner);denied(()->core.validateRenderPermit(finalObserver,newOwner,after),"wearer Auth expiry aborts render chunk");core.reconcile();check(runtime.worn.get(owner.connection).equals("builtin_default"),"wearer Auth expiry resets appearance");core.close();registry.close();
        var disabled=new YsmAssetCoordinator(server::isSameThread);var none=states.get("pendingA");disabled.stage(none,YsmAssetProtocolTest.generation(none));check(disabled.list(YsmTrustedPlayer.capture(observer)).isEmpty(),"unknown upload remains excluded");denied(()->disabled.renderPermit(YsmTrustedPlayer.capture(observer),()->new YsmAssetCoordinator.Identity("10001",owner.getUUID(),owner.connection),disabled.revision()),"A does not activate unvalidated input/default runtime");disabled.close();
    }
    public static void main(String[] args)throws Exception{
        var root=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonObject();a=root.get("assetA").getAsString();b=root.get("assetB").getAsString();p=root.get("contentId").getAsString();sha=root.get("sha256").getAsString();for(var row:root.getAsJsonArray("cases")){var entry=row.getAsJsonObject();states.put(entry.get("name").getAsString(),YsmAssetSnapshot.parseTrusted(entry.get("snapshot").toString()));}
        policyAndTransitions();identityFences();System.out.println("{\"passed\":true,\"checks\":"+checks+",\"privateAppearancePolicy\":\"A_OWNER_SELECTION_OBSERVER_RENDER\",\"renderResourceExtractionPrevented\":false,\"actualWebSnapshots\":true,\"nativeTransitionMechanismExecuted\":false,\"nativePort\":\"explicit fixtures\",\"minecraftStarted\":false,\"productionActivated\":false}");
    }
}
